// Import React and useState from 'react' here
import React, { useState } from 'react';

// Import useEffect and useRef from 'react' here
import { useEffect, useRef } from 'react';

// Add TypeScript interface for the hook's return value here
interface UseWebSocketReturn {
  sendMessage: (message: string) => void;
  lastMessage: string | null;
  readyState: number;
}

// Create the useWebSocket custom hook function here
function useWebSocket(): UseWebSocketReturn {
  // Initialize state for lastMessage here
  const [lastMessage, setLastMessage] = useState<string | null>(null);

  // Initialize state for readyState here
  const [readyState, setReadyState] = useState<number>(WebSocket.CONNECTING);

  // Create a ref to store the WebSocket instance here
  const socketRef = useRef<WebSocket | null>(null);

  // Define the sendMessage function here
  const sendMessage = (message: string) => {
    if (socketRef.current && socketRef.current.readyState === WebSocket.OPEN) {
      socketRef.current.send(message);
    }
  };

  // Set up the useEffect hook for WebSocket connection here
  useEffect(() => {
    const socket = new WebSocket('ws://localhost:8080');
    socketRef.current = socket;

    // Implement WebSocket event handlers here
    socket.onopen = () => {
      setReadyState(WebSocket.OPEN);
    };

    socket.onmessage = (event) => {
      setLastMessage(event.data);
    };

    socket.onclose = () => {
      setReadyState(WebSocket.CLOSED);
    };

    // Add cleanup function here
    return () => {
      socket.close();
    };
  }, []);

  // Return the hook's interface object here
}
